// The win photo used by the link-preview card, inlined as a data URI.
//
// Inlined on purpose: the OG route renders at the edge, so a same-origin asset fetch
// would need an absolute URL that differs between production and preview deploys, and
// any network hiccup would blank the card. Compressed to ~74KB at 820x784 (2x the
// 410x392 slot it renders into).
export const WIN_PHOTO =
  'data:image/jpeg;base64,';
